-- D039: random maps. A world created with RANDOM_MAPS=1 stores its own full template (generated by the server,
-- never regenerated by clients). Static worlds (city-coast-01, farm-valley-01, farm-g1) have no row here.
CREATE TABLE world_templates (
  world_id          uuid PRIMARY KEY REFERENCES worlds (id) ON DELETE CASCADE,
  map_id            text NOT NULL,
  generator_version text NOT NULL,
  seed              bigint NOT NULL,
  attempt           integer NOT NULL,
  template          jsonb NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now()
);
